from pathlib import Path
from html import escape
OUT=Path(__file__).resolve().parents[1] / 'assets/images/research/20261031';OUT.mkdir(parents=True,exist_ok=True)
N='#0B2045';B='#1767B4';O='#F06A22';T='#087E83';G='#8091AA'
class Fig:
 def __init__(self,title,desc):
  self.s=[f'''<svg xmlns="http://www.w3.org/2000/svg" width="1536" height="1024" viewBox="0 0 1536 1024" role="img" aria-labelledby="title desc"><title id="title">{escape(title)}</title><desc id="desc">{escape(desc)}</desc><defs>''']
  for c in [N,B,O,T,G]:self.s.append(f'<marker id="a{c[1:]}" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L10 5L0 10Z" fill="{c}"/></marker>')
  self.s.append('</defs><rect width="1536" height="1024" fill="white"/><g font-family="Liberation Serif, Times New Roman, serif" fill="'+N+'">');self.text(768,58,title,42,True,'middle')
 def text(self,x,y,t,size=24,bold=False,anchor='start',color=N):self.s.append(f'<text x="{x}" y="{y}" font-size="{size}" font-weight="{"bold" if bold else "normal"}" text-anchor="{anchor}" fill="{color}">{escape(t)}</text>')
 def line(self,pts,color=N,dash=False,arrow=True):self.s.append(f'<polyline points="{pts}" fill="none" stroke="{color}" stroke-width="2.5" stroke-linejoin="round"'+(' stroke-dasharray="7 6"' if dash else '')+(f' marker-end="url(#a{color[1:]})"' if arrow else '')+'/>')
 def box(self,x,y,w,h,title,lines=(),color=N,fill='#FFFFFF'):
  self.s.append(f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="8" fill="{fill}" stroke="{color}" stroke-width="2.3"/>');self.text(x+w/2,y+32,title,27,True,'middle')
  for i,l in enumerate(lines):self.text(x+w/2,y+65+28*i,l,23,False,'middle')
 def lane(self,y,n,title):
  self.line(f'24,{y} 1512,{y}',G,arrow=False);self.s.append(f'<circle cx="46" cy="{y+36}" r="21" fill="{N}"/>');self.text(46,y+44,str(n),27,True,'middle','white');self.text(81,y+46,title,32,True)
 def save(self,name): (OUT/name).write_text(''.join(self.s)+'</g></svg>')
